import caseStudies from './caseStudies.json';
import localImages from './imageManifest.json';

// Case-study images live in the repo, in public/images/cs_<id>.<ext>.
// imageManifest.json is generated by scripts/build-image-manifest.js before
// every start/build; the nightly sync adds the images of new cases.
const imageMap = {};
for (const study of caseStudies) {
  const file = localImages[study.id];
  if (file) imageMap[study.id] = `${process.env.PUBLIC_URL}/images/${file}`;
}

export default imageMap;
